cat > public/app.js <<'EOF'
const form = document.getElementById("task-form");
const titleInput = document.getElementById("task-title");
const list = document.getElementById("task-list");
const trash = document.getElementById("trash-list");
const trashSection = document.getElementById("trash");
const status = document.getElementById("status");

function actionButton(label, onClick) {
  const button = document.createElement("button");
  button.type = "button";
  button.textContent = label;
  button.addEventListener("click", onClick);
  return button;
}

function taskItem(task, label, onClick) {
  const item = document.createElement("li");
  const title = document.createElement("span");
  title.textContent = task.title;
  item.append(title, " ", actionButton(label, () => onClick(task)));
  return item;
}

async function showTasks() {
  const [active, deleted] = await Promise.all([
    fetch("/api/tasks").then((response) => response.json()),
    fetch("/api/tasks/deleted").then((response) => response.json()),
  ]);
  list.replaceChildren(...active.tasks.map((task) => taskItem(task, "Delete", deleteTask)));
  trash.replaceChildren(...deleted.tasks.map((task) => taskItem(task, "Restore", restoreTask)));
  trashSection.hidden = deleted.tasks.length === 0;
}

/** Runs a change, then redraws; a failed change is reported instead of silently ignored. */
async function change(request, failure) {
  status.textContent = "";
  try {
    const response = await request();
    // A 404 means the task is already in the wanted state (for example, deleted in another tab).
    if (!response.ok && response.status !== 404) status.textContent = failure;
  } catch {
    status.textContent = failure;
  }
  await showTasks();
}

function deleteTask(task) {
  return change(
    () => fetch(`/api/tasks/${task.id}`, { method: "DELETE" }),
    "Could not delete the task. Try again.",
  );
}

function restoreTask(task) {
  return change(
    () => fetch(`/api/tasks/${task.id}/restore`, { method: "POST" }),
    "Could not restore the task. Try again.",
  );
}

form.addEventListener("submit", async (event) => {
